(async () => {
  try {
    const page = figma.createPage();
    page.name = "TitikTemu · Desain";
    await figma.setCurrentPageAsync(page);

    const frames = {}; // kode layar -> { node, def }
    const sections = [];
    let y = 0;
    for (const sec of DATA.sections) {
      const section = figma.createSection();
      section.name = sec.name;
      section.x = 0;
      section.y = y;
      const PAD = 80, GAP = 80, HEAD = 120;
      // satu baris = satu alur (mis. Data diri, PS dan jam, Bayar); tiap baris ditumpuk ke bawah
      const rowX = {}, ROWH = sec.h + 140;
      let maxX = 0, maxRow = 0;
      for (const def of sec.frames) {
        const node = figma.createNodeFromSvg(def.svg);
        node.name = def.name;
        section.appendChild(node);
        const r = def.row || 0;
        rowX[r] = rowX[r] === undefined ? PAD : rowX[r];
        node.x = rowX[r];
        node.y = HEAD + r * ROWH;
        rowX[r] += node.width + GAP;
        maxX = Math.max(maxX, rowX[r]);
        maxRow = Math.max(maxRow, r);
        frames[def.code] = { node, def };
      }
      section.resizeWithoutConstraints(maxX - GAP + PAD, HEAD + maxRow * ROWH + sec.h + PAD);
      sections.push(section);
      y += section.height + 240;
    }

    // Prototype: tiap hotspot = persegi transparan di atas tombol, diberi aksi klik -> pindah layar
    let links = 0, gagal = 0;
    for (const { node, def } of Object.values(frames)) {
      for (const h of def.hot) {
        const target = frames[h.to];
        if (!target) continue;
        const r = figma.createRectangle();
        r.name = "Hotspot → " + h.name;
        node.appendChild(r);
        r.x = h.x;
        r.y = h.y;
        r.resize(h.w, h.h);
        r.fills = [{ type: "SOLID", color: { r: 1, g: 1, b: 1 }, opacity: 0.01 }];
        try {
          await r.setReactionsAsync([
            {
              trigger: { type: "ON_CLICK" },
              actions: [{ type: "NODE", destinationId: target.node.id, navigation: "NAVIGATE", transition: null, resetVideoPosition: false }],
            },
          ]);
          links++;
        } catch (e) {
          gagal++;
        }
      }
    }
    try {
      page.flowStartingPoints = [
        { nodeId: frames["C1"].node.id, name: "Customer: Pesan PS" },
        { nodeId: frames["A1"].node.id, name: "Admin: Riwayat" },
      ];
    } catch (e) {}

    figma.viewport.scrollAndZoomIntoView(sections);
    figma.notify("Selesai: 2 Section, " + Object.keys(frames).length + " layar, " + links + " tautan prototype" + (gagal ? " (" + gagal + " gagal)" : "") + ".", { timeout: 8000 });
  } catch (e) {
    figma.notify("Gagal: " + e.message, { error: true, timeout: 10000 });
    console.error(e);
  }
  figma.closePlugin();
})();
